submit("""CREATE OR REPLACE FUNCTION get_spread_rate(p_metrics jsonb)
RETURNS numeric
LANGUAGE plpgsql
IMMUTABLE
AS $$
DECLARE
    best_ask   numeric;
    best_bid   numeric;
    mid_price  numeric;
    spread_pct numeric;
BEGIN
    -- Extract values from the JSON blob; they are stored as text, so cast to numeric
    best_ask  := (p_metrics->>''best_ask'')::numeric;
    best_bid  := (p_metrics->>''best_bid'')::numeric;
    mid_price := (p_metrics->>''mid_price'')::numeric;

    -- Guard against division by zero or missing data
    IF best_ask IS NULL OR best_bid IS NULL OR mid_price IS NULL OR mid_price = 0 THEN
        RETURN NULL;
    END IF;

    -- Calculate spread percentage (spread rate)
    spread_pct := (best_ask - best_bid) / mid_price * 100;

    RETURN spread_pct;
END;
$$;""")

