submit("""CREATE OR REPLACE FUNCTION get_spread_rate(p_metrics jsonb)
RETURNS numeric
LANGUAGE plpgsql
IMMUTABLE
AS $$
DECLARE
    sp_text text;
    sp_num  numeric;
BEGIN
    -- Extract the spread percentage string (e.g., '11.99%')
    sp_text := p_metrics->>'spread_pct';

    IF sp_text IS NULL THEN
        RETURN NULL;
    END IF;

    -- Remove the trailing percent sign and cast to numeric
    sp_num := replace(sp_text, '%', '')::numeric;

    RETURN sp_num;
END;
$$;""")

